import{c as a,Q as e,j as d,m as s}from"./chunks/framework.DOi4mjdC.js";const r="/assets/ScaleA%E5%9C%A8L0A%E7%9A%84%E5%88%86%E5%BD%A2%E6%8E%92%E5%B8%83.CRB28ra2.png",o="/assets/Nd2Nz%E8%BD%AC%E6%8D%A2%E7%A4%BA%E6%84%8F%E5%9B%BE.D-lmqjWK.png",A=JSON.parse('{"title":"Load2DMX","description":"","frontmatter":{},"headers":[{"level":1,"title":"Load2DMX","slug":"load2dmx"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"}],"relativePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load2DMX.md","filePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load2DMX.md"}'),l={name:"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load2DMX.md"};function n(i,t,p,c,h,m){return e(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="load2dmx" tabindex="-1">Load2DMX <a class="header-anchor" href="#load2dmx" aria-label="Permalink to &quot;Load2DMX&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>x</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Load2D支持如下数据通路的搬运：</p><p>GM-&gt;A1; GM-&gt;B1; GM-&gt;A2; GM-&gt;B2;</p><p>A1-&gt;A2; B1-&gt;B2。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>Load2DMX接口</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U = T&gt;</span></span>\n<span class="line"><span>__aicore__ inline void LoadData(const LocalTensor&lt;U&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const LocalTensor&lt;fp8_e8m0_t&gt;&amp; srcMx, const LoadData2DParamsV2&amp; loadDataParams, const LoadData2DMxParams&amp; loadMxDataParams)</span></span></code></pre></div></li><li><p>Load2Dv2MX接口，支持源操作数和目的操作数数据类型不一致</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U&gt;</span></span>\n<span class="line"><span>__aicore__ inline void LoadData(const LocalTensor&lt;U&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src0, const LocalTensor&lt;fp8_e8m0_t&gt;&amp; srcMx, const LoadData2DParamsV2&amp; loadDataParams, const LoadData2DMxParams&amp; loadMxDataParams)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>源操作数和目的操作数的数据类型。 Load2DMX接口 Ascend 950PR/Ascend 950DT，支持数据类型为：fp4x2_e2m1_t/fp4x2_e1m2_t/fp8_e4m3fn_t/fp8_e5m2_t</td></tr><tr><td>U</td><td>针对Load2DMX接口，U用来表示dst的数据类型，当src为fp8_e4m3fn_t、fp8_e5m2_t时，U需为T对应的MX数据类型，即AscendC::mx_fp8_e4m3_t和AscendC::mx_fp8_e5m2_t，否则编译失败。除此之外的数据类型要求T和U一致。</td></tr></tbody></table><p><strong>表 2</strong> 通用参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。 数据连续排列顺序由目的操作数所在TPosition决定，具体约束如下： A2：ZZ格式/NZ格式；对应的分形大小为16 * (32B / sizeof(T))。B2：ZN格式；对应的分形大小为 (32B / sizeof(T)) * 16。A1/B1：无格式要求，一般情况下为NZ格式。NZ格式下，对应的分形大小为16 * (32B / sizeof(T))。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor或GlobalTensor。 数据类型需要与dst保持一致。</td></tr><tr><td>srcMx</td><td>输入</td><td>源操作数，类型为LocalTensor，仅支持fp8_e8m0_t类型。</td></tr><tr><td>loadDataParams</td><td>输入</td><td>LoadData参数结构体，类型为： LoadData2DMxParams，具体参考表3。 上述结构体参数定义请参考${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_mm.h，${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表 3</strong> LoadData2DMxParams结构体参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>xStartPosition</td><td>源矩阵X轴方向的起始位置，即M维度方向，单位为1个分形（1个单位代表一个32B的分形）。</td></tr><tr><td>yStartPosition</td><td>源矩阵Y轴方向的起始位置，即K维度方向，单位为32B。</td></tr><tr><td>xStep</td><td>源矩阵X轴方向搬运长度，即M维度方向，单位为1个分形（1个单位代表一个32B的分形）。取值范围：xStep∈[0, 255]。</td></tr><tr><td>yStep</td><td>源矩阵Y轴方向搬运长度，即K维度方向，单位为32B。取值范围：yStep∈[0, 255]。</td></tr><tr><td>srcStride</td><td>源矩阵X方向前一个分形起始地址与后一个分形起始地址的间隔，单位为32B。</td></tr><tr><td>dstStride</td><td>目标矩阵X方向前一个分形起始地址与后一个分形起始地址的间隔，单位为32B。</td></tr></tbody></table><p>下面通过一个具体的示例来解释LoadData2DMX结构体参数。假设A矩阵shape为（M，K），则ScaleA矩阵shape为（M，K/32），ScaleA数据类型为fp8_e8m0_t，ScaleA矩阵分形排布见<a href="#fig138710913432">图1</a>。</p><p><strong>图 1</strong> ScaleA在L0A的分形排布<br><img src="'+r+'" alt="" title="ScaleA在L0A的分形排布"></p><p>下图为ScaleA从L1搬运至L0A过程中的配置参数示意。每一行为32Byte，对应着<a href="#fig138710913432">图1</a>中的一个分形。xStep为M维度分形的个数，如图中的xStep = M / 16 = 3，yStep为K维度32Byte的个数，如图中的yStep = K / 32 / 2 = 21，srcStride和dstStride同理，表示在K维度上32Byte的个数。</p><p><img src="'+o+'" alt=""></p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p>',24)])])}const D=a(l,[["render",n]]);export{A as __pageData,D as default};
